// Interaction only. All page text is in the HTML (generated by scripts/build.py).
(function () {
  const strings = JSON.parse(document.getElementById("page-strings").textContent);
  const body = document.getElementById("system-rows");
  const search = document.getElementById("system-search");
  const category = document.getElementById("category-filter");
  const rating = document.getElementById("rating-filter");
  const count = document.getElementById("matrix-count");
  const groups = ["anchor", "coding", "runtime", "persistent", "workplace"];
  let open = new Set(["anchor"]);

  function render() {
    const q = search.value.trim().toLowerCase();
    const cat = category.value;
    const rat = rating.value;
    const filtering = q !== "" || cat !== "all" || rat !== "all";
    let matched = 0;
    groups.forEach(g => {
      const expanded = filtering || open.has(g);
      let visibleInGroup = 0;
      body.querySelectorAll(`tr.data-row[data-group="${g}"]`).forEach(row => {
        const ok = row.dataset.name.includes(q) && (cat === "all" || cat === g) && (rat === "all" || row.dataset.ratings.split(" ").includes(rat));
        if (ok) { matched++; visibleInGroup++; }
        row.hidden = !(ok && expanded);
        const ev = document.getElementById(row.querySelector(".evidence-toggle").getAttribute("aria-controls"));
        if (row.hidden) ev.hidden = true;
        else ev.hidden = row.querySelector(".evidence-toggle").getAttribute("aria-expanded") !== "true";
      });
      const head = body.querySelector(`tr.system-group-row[data-group="${g}"]`);
      head.hidden = visibleInGroup === 0;
      const btn = head.querySelector("button");
      btn.disabled = filtering;
      btn.setAttribute("aria-expanded", String(expanded));
      btn.querySelector("span").textContent = expanded ? "−" : "+";
    });
    count.textContent = strings.count.replace("{n}", matched).replace("{total}", strings.total);
    document.getElementById("expand-groups").disabled = filtering;
    document.getElementById("collapse-groups").disabled = filtering;
  }

  body.addEventListener("click", ev => {
    const groupBtn = ev.target.closest(".system-group-toggle");
    if (groupBtn) {
      const g = groupBtn.dataset.group;
      open.has(g) ? open.delete(g) : open.add(g);
      render();
      return;
    }
    const evBtn = ev.target.closest(".evidence-toggle");
    if (evBtn) {
      const row = document.getElementById(evBtn.getAttribute("aria-controls"));
      const isOpen = evBtn.getAttribute("aria-expanded") === "true";
      evBtn.setAttribute("aria-expanded", String(!isOpen));
      evBtn.textContent = isOpen ? evBtn.dataset.show : evBtn.dataset.hide;
      row.hidden = isOpen;
    }
  });
  [search, category, rating].forEach(el => el.addEventListener(el === search ? "input" : "change", render));
  document.getElementById("expand-groups").addEventListener("click", () => { open = new Set(groups); render(); });
  document.getElementById("collapse-groups").addEventListener("click", () => { open = new Set(); render(); });

  document.getElementById("copy-citation").addEventListener("click", async () => {
    const text = document.getElementById("bibtex").textContent;
    const status = document.getElementById("copy-status");
    try {
      if (navigator.clipboard && window.isSecureContext) await navigator.clipboard.writeText(text);
      else {
        const area = document.createElement("textarea");
        area.value = text; area.setAttribute("readonly", ""); area.style.position = "fixed"; area.style.opacity = "0";
        document.body.appendChild(area); area.select();
        const ok = document.execCommand("copy"); area.remove();
        if (!ok) throw new Error("copy unavailable");
      }
      status.textContent = strings.copied;
    } catch (_) { status.textContent = strings.fail; }
  });

  render();
})();
